set -euo pipefail
HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
APPLY=0
for arg in "$@"; do if [[ "$arg" == "--apply" ]]; then APPLY=1; fi; done
[[ $APPLY -eq 1 ]] || { echo "Dry-run policy: rerun with --apply after review${DRY_RUN_NOTE:-}."; exit 0; }
[[ $EUID -eq 0 ]] || { echo "Run as root with sudo." >&2; exit 2; }

ROOT="$(cd "$(dirname "$0")/../.." && pwd)"
SOURCE="$ROOT/HYDRA-UMC-TWIN"
TARGET=/opt/hydra-umc/twin
DEPLOY_CONTRACT=1
source "$HERE/deploy_lib.sh"
deploy_begin HYDRA-UMC-TWIN "$TARGET"
SVC_USER="hydra-umc-twin"

[[ -f "$SOURCE/hydra-umc.project.json" ]] || { echo "HYDRA-UMC-TWIN source is incomplete: $SOURCE" >&2; exit 2; }
[[ -f "$SOURCE/systemd/hydra-umc-twin.service" ]] || { echo "HYDRA-UMC-TWIN has no unit hydra-umc-twin.service: $SOURCE" >&2; exit 2; }
if ! id -u "$SVC_USER" >/dev/null 2>&1; then
  useradd --system --home "$TARGET" --no-create-home --shell /usr/sbin/nologin "$SVC_USER"
fi
install -d -o root -g root -m 0755 "$TARGET"
HOOK="$HERE/build_hooks/twin.sh"
[[ -f "$HOOK" ]] || { echo "HYDRA-UMC-TWIN needs its build hook build_hooks/twin.sh: $HOOK" >&2; exit 2; }
source "$HOOK"
install -m 0644 "$SOURCE/systemd/hydra-umc-twin.service" /etc/systemd/system/hydra-umc-twin.service
install -m 0644 "$SOURCE/hydra-umc.project.json" "$TARGET/hydra-umc.project.json"
systemctl daemon-reload
deploy_finish HYDRA-UMC-TWIN "$TARGET"
echo "twin installed. Enable manually after review: systemctl enable --now hydra-umc-twin"
if declare -F hook_after_install >/dev/null; then hook_after_install; fi
source "$HERE/service_registry.sh"
announce_health HYDRA-UMC-TWIN
